// Memory Allocation
size_t buffer_size = 512;
void* ptr = malloc(buffer_size);

// Check and Usage
if (ptr != NULL) {
    // Memory is available here
    // ...
}

// Deallocate the memory block pointed to by ptr
free(ptr);

// Standard practice: prevent dangling pointer access
ptr = NULL;

// Warning: Calling free(NULL) has no effect.
// Warning: Double free() results in Undefined Behavior (UB).
